#include <ATen/ATen.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>

#include <cuda_bf16.h>
#include <cuda_fp16.h>
#include <cuda_fp8.h>
#include <cuda_runtime.h>

#include <cstdint>
#include <vector>

namespace {

constexpr int kHeadDim = 128;
constexpr int kRopeDim = 64;
constexpr int kVec = 4;
constexpr int kWarp = 32;
constexpr int kBlockThreads = 128;
constexpr int kWarpsPerBlock = kBlockThreads / kWarp;
constexpr float kFP8E4M3Max = 448.0f;

__device__ __forceinline__ float load_as_float(const half* p) { return __half2float(*p); }
__device__ __forceinline__ float load_as_float(const __nv_bfloat16* p) { return __bfloat162float(*p); }

template <typename T>
__device__ __forceinline__ float load_t(const void* base, int64_t idx) {
  return load_as_float(reinterpret_cast<const T*>(base) + idx);
}

__device__ __forceinline__ float warp_reduce_max(float v) {
#pragma unroll
  for (int mask = 16; mask > 0; mask >>= 1) {
    v = fmaxf(v, __shfl_xor_sync(0xffffffffu, v, mask, kWarp));
  }
  return v;
}

__device__ __forceinline__ uint16_t pack_fp8_pair(float x, float y) {
  x = fminf(fmaxf(x, -kFP8E4M3Max), kFP8E4M3Max);
  y = fminf(fmaxf(y, -kFP8E4M3Max), kFP8E4M3Max);
  float2 f2 = make_float2(x, y);
  __nv_fp8x2_e4m3 v(f2);
  return v.__x;
}

template <typename DType, typename PosT>
__global__ __launch_bounds__(kBlockThreads, 16)
void indexer_kernel(const void* __restrict__ q_input,
                    const void* __restrict__ weight,
                    uint8_t* __restrict__ q_fp8,
                    float* __restrict__ weights_out,
                    float weight_scale,
                    const float* __restrict__ freqs,
                    const PosT* __restrict__ positions,
                    int total_rows,
                    int num_heads) {
  const int warp_id = threadIdx.x / kWarp;
  const int lane = threadIdx.x & (kWarp - 1);
  const int row = blockIdx.x * kWarpsPerBlock + warp_id;
  if (row >= total_rows) return;

  const int batch = row / num_heads;
  const int pos = static_cast<int>(positions[batch]);
  const int elem0 = lane * kVec;

  float d0 = load_t<DType>(q_input, static_cast<int64_t>(row) * kHeadDim + elem0 + 0);
  float d1 = load_t<DType>(q_input, static_cast<int64_t>(row) * kHeadDim + elem0 + 1);
  float d2 = load_t<DType>(q_input, static_cast<int64_t>(row) * kHeadDim + elem0 + 2);
  float d3 = load_t<DType>(q_input, static_cast<int64_t>(row) * kHeadDim + elem0 + 3);

  // RoPE is applied only to the trailing 64 dimensions.  With four values per
  // lane, those are lanes 16..31.  freqs is real/imag interleaved with shape
  // [max_seq_len, 64].
  if (lane >= 16) {
    const int foff = (lane - 16) * kVec;
    const float fxr = freqs[static_cast<int64_t>(pos) * kRopeDim + foff + 0];
    const float fxi = freqs[static_cast<int64_t>(pos) * kRopeDim + foff + 1];
    const float fyr = freqs[static_cast<int64_t>(pos) * kRopeDim + foff + 2];
    const float fyi = freqs[static_cast<int64_t>(pos) * kRopeDim + foff + 3];
    const float x_real = d0, x_imag = d1, y_real = d2, y_imag = d3;
    d0 = x_real * fxr - x_imag * fxi;
    d1 = x_real * fxi + x_imag * fxr;
    d2 = y_real * fyr - y_imag * fyi;
    d3 = y_real * fyi + y_imag * fyr;
  }

  // SGLang lane-major 128-point Hadamard.  Two butterflies inside each
  // four-element lane, then five xor shuffles across the 32 lanes.
  {
    const float a0 = d0, a1 = d1, a2 = d2, a3 = d3;
    d0 = a0 + a1;
    d1 = a0 - a1;
    d2 = a2 + a3;
    d3 = a2 - a3;
  }
  {
    const float a0 = d0, a1 = d1, a2 = d2, a3 = d3;
    d0 = a0 + a2;
    d1 = a1 + a3;
    d2 = a0 - a2;
    d3 = a1 - a3;
  }
#pragma unroll
  for (int mask = 1; mask < kWarp; mask <<= 1) {
    const float o0 = __shfl_xor_sync(0xffffffffu, d0, mask, kWarp);
    const float o1 = __shfl_xor_sync(0xffffffffu, d1, mask, kWarp);
    const float o2 = __shfl_xor_sync(0xffffffffu, d2, mask, kWarp);
    const float o3 = __shfl_xor_sync(0xffffffffu, d3, mask, kWarp);
    if (lane & mask) {
      d0 = o0 - d0; d1 = o1 - d1; d2 = o2 - d2; d3 = o3 - d3;
    } else {
      d0 = d0 + o0; d1 = d1 + o1; d2 = d2 + o2; d3 = d3 + o3;
    }
  }

  constexpr float inv_sqrt_128 = 0.08838834764831845f;
  d0 *= inv_sqrt_128;
  d1 *= inv_sqrt_128;
  d2 *= inv_sqrt_128;
  d3 *= inv_sqrt_128;

  float local_max = fmaxf(fmaxf(fabsf(d0), fabsf(d1)), fmaxf(fabsf(d2), fabsf(d3)));
  const float abs_max = warp_reduce_max(local_max);
  const float scale = fmaxf(1.0e-4f, abs_max) / kFP8E4M3Max;
  const float inv_scale = 1.0f / scale;

  uint16_t* out16 = reinterpret_cast<uint16_t*>(q_fp8 + static_cast<int64_t>(row) * kHeadDim);
  out16[lane * 2 + 0] = pack_fp8_pair(d0 * inv_scale, d1 * inv_scale);
  out16[lane * 2 + 1] = pack_fp8_pair(d2 * inv_scale, d3 * inv_scale);

  // Every lane computes the same value.  Store from lane 0 to avoid benign
  // races and match weights_out shape [B,H,1] flattened by row.
  if (lane == 0) {
    const float w = load_t<DType>(weight, row);
    weights_out[row] = w * weight_scale * scale;
  }
}

template <typename DType, typename PosT>
void launch_typed(const at::Tensor& q_input,
                  const at::Tensor& weight,
                  at::Tensor& q_fp8,
                  at::Tensor& weights_out,
                  double weight_scale,
                  const at::Tensor& freqs,
                  const at::Tensor& positions) {
  const int B = static_cast<int>(q_input.size(0));
  const int H = static_cast<int>(q_input.size(1));
  const int total = B * H;
  if (total == 0) return;
  const dim3 block(kBlockThreads);
  const dim3 grid((total + kWarpsPerBlock - 1) / kWarpsPerBlock);
  auto stream = at::cuda::getCurrentCUDAStream();
  indexer_kernel<DType, PosT><<<grid, block, 0, stream>>>(
      q_input.const_data_ptr(), weight.const_data_ptr(),
      reinterpret_cast<uint8_t*>(q_fp8.data_ptr()), weights_out.data_ptr<float>(),
      static_cast<float>(weight_scale), freqs.const_data_ptr<float>(),
      positions.const_data_ptr<PosT>(), total, H);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
}

}  // namespace

std::vector<at::Tensor> indexer_cuda(at::Tensor q_input,
                                     at::Tensor weight,
                                     double weight_scale,
                                     at::Tensor freqs,
                                     at::Tensor positions) {
  const at::cuda::CUDAGuard device_guard(q_input.device());
  auto q_fp8 = at::empty(q_input.sizes(), q_input.options().dtype(at::ScalarType::Float8_e4m3fn));
  auto weights_out = at::empty({q_input.size(0), q_input.size(1), 1}, q_input.options().dtype(at::kFloat));

  if (q_input.scalar_type() == at::kHalf) {
    if (positions.scalar_type() == at::kInt) {
      launch_typed<half, int32_t>(q_input, weight, q_fp8, weights_out, weight_scale, freqs, positions);
    } else {
      launch_typed<half, int64_t>(q_input, weight, q_fp8, weights_out, weight_scale, freqs, positions);
    }
  } else {
    if (positions.scalar_type() == at::kInt) {
      launch_typed<__nv_bfloat16, int32_t>(q_input, weight, q_fp8, weights_out, weight_scale, freqs, positions);
    } else {
      launch_typed<__nv_bfloat16, int64_t>(q_input, weight, q_fp8, weights_out, weight_scale, freqs, positions);
    }
  }
  return {q_fp8, weights_out};
}
